function ascii(a,b){return a<b?-1:a>b?1:0}
function canonOrder(o){
  const choices=o.choices.map(c=>({id:c.id,items:Object.fromEntries(Object.keys(c.items).sort(ascii).map(k=>[k,c.items[k]]))})).sort((a,b)=>ascii(a.id,b.id)||ascii(JSON.stringify(a.items),JSON.stringify(b.items)));
  return JSON.stringify({id:o.id,value:o.value,group:o.group,choices});
}
export function allocate({now,on_hand,holds,orders}){
  const skus=Object.keys(on_hand), remaining={...on_hand};
  const blocked=new Set();
  for(const h of holds){
    if(h.state==='reserved' && h.expires_at>now){remaining[h.sku]-=h.quantity;blocked.add(h.order_id);}
    else if(h.state==='committed'||h.state==='cancelled') blocked.add(h.order_id);
  }
  const byId=new Map();
  for(const o of orders){
    const sig=canonOrder(o);
    if(byId.has(o.id)){if(byId.get(o.id).sig!==sig)throw new Error(`Conflicting order ID: ${o.id}`);}
    else byId.set(o.id,{o,sig});
  }
  const candidates=[...byId.values()].map(x=>x.o).filter(o=>!blocked.has(o.id)).sort((a,b)=>ascii(a.id,b.id));
  let bestValue=0,bestCount=0,best=[]; const used=Object.fromEntries(skus.map(s=>[s,0]));
  function better(v, chosen){
    if(v!==bestValue)return v>bestValue;
    if(chosen.length!==bestCount)return chosen.length>bestCount;
    const pairs=chosen.map(x=>({order_id:x.o.id,choice_id:x.c.id})).sort((a,b)=>ascii(a.order_id,b.order_id)||ascii(a.choice_id,b.choice_id));
    for(let i=0;i<pairs.length;i++){
      let z=ascii(pairs[i].order_id,best[i].order_id);if(!z)z=ascii(pairs[i].choice_id,best[i].choice_id);if(z)return z<0;
    }
    return false;
  }
  function dfs(i,v,chosen,groups){
    if(i===candidates.length){if(better(v,chosen)){bestValue=v;bestCount=chosen.length;best=chosen.slice();}return;}
    dfs(i+1,v,chosen,groups);
    const o=candidates[i];if(o.group!==null&&groups.has(o.group))return;
    for(const c of o.choices){
      let ok=true;for(const [s,q] of Object.entries(c.items))if(remaining[s]-used[s]<q){ok=false;break;}
      if(!ok)continue;
      for(const [s,q] of Object.entries(c.items))used[s]+=q;
      if(o.group!==null)groups.add(o.group);chosen.push({o,c});dfs(i+1,v+o.value,chosen,groups);chosen.pop();if(o.group!==null)groups.delete(o.group);
      for(const [s,q] of Object.entries(c.items))used[s]-=q;
    }
  }
  dfs(0,0,[],new Set());
  const allocations=best.map(x=>({order_id:x.o.id,choice_id:x.c.id})).sort((a,b)=>ascii(a.order_id,b.order_id)||ascii(a.choice_id,b.choice_id));
  const out={...on_hand};for(const s of skus)out[s]-=Object.values(used).length; // replaced below from best consumption
  const final={...on_hand};
  for(const h of holds)if(h.state==='reserved'&&h.expires_at>now)final[h.sku]-=h.quantity;
  for(const x of best)for(const [s,q] of Object.entries(x.c.items))final[s]-=q;
  return {value:bestValue,count:bestCount,allocations,remaining:final};
}

